detaileddescription.para:
Example: auto rebalancer = std::make_unique<AutoRebalancer>(
      topology, load_detector, metrics, migrator
  ); rebalancer->start();

memberdef.definition:
using themis::sharding::S3DownloadFn = std::function<bool(const std::string& bucket,
                                       const std::string& remote_path,
                                       const std::string& local_path)>

using themis::sharding::S3UploadFn = std::function<bool(const std::string& bucket,
                                     const std::string& local_path,
                                     const std::string& remote_path,
                                     const std::map<std::string, std::string>& metadata)>

using themis::sharding::AzureUploadFn = std::function<bool(const std::string& account,
                                        const std::string& container,
                                        const std::string& local_path,
                                        const std::string& remote_path,
                                        const std::map<std::string, std::string>& metadata)>

using themis::sharding::AzureDeleteFn = std::function<bool(const std::string& account,
                                        const std::string& container,
                                        const std::string& remote_path)>

using themis::sharding::AzureListFn = std::function<std::vector<std::string>(const std::string& account,
                                                          const std::string& container,
                                                          const std::string& prefix)>

using themis::sharding::AzureExistsFn = std::function<bool(const std::string& account,
                                        const std::string& container,
                                        const std::string& remote_path)>

using themis::sharding::GCSUploadFn = std::function<bool(const std::string& bucket,
                                      const std::string& local_path,
                                      const std::string& remote_path,
                                      const std::map<std::string, std::string>& metadata)>

using themis::sharding::GCSDownloadFn = std::function<bool(const std::string& bucket,
                                        const std::string& remote_path,
                                        const std::string& local_path)>

using themis::sharding::ApplyOperationsCallback = 
std::function<bool(const std::string& txn_id,
                   const nlohmann::json& ops,
                   int64_t commit_ts)>

using themis::sharding::ValidateAndLockCallback = 
std::function<bool(const std::string& txn_id,
                   const nlohmann::json& ops)>
